#!/usr/bin/env node
/*
 * extract.js - reconstruct the in-memory image of an ELF executable and emit
 * every 4-byte little-endian word as a JSON object:
 *
 *     { "<virtual address>": <uint32 value>, ... }
 *
 * The ELF is loaded the way a simple loader would place its PT_LOAD segments:
 * each segment is mapped at  LOAD_BASE + p_vaddr  and its p_filesz bytes are
 * copied from p_offset.  Words are read as unsigned 32-bit little-endian
 * values (x86-64).
 *
 * Usage: node extract.js /path/to/binary > out.json
 */

'use strict';

const fs = require('fs');

// Base address the executable image is mapped at.
const LOAD_BASE = 0x400000;

function readUInt(buf, off, size, le) {
  if (size === 8) {
    return le ? buf.readBigUInt64LE(off) : buf.readBigUInt64BE(off);
  }
  if (size === 4) {
    return le ? buf.readUInt32LE(off) : buf.readUInt32BE(off);
  }
  if (size === 2) {
    return le ? buf.readUInt16LE(off) : buf.readUInt16BE(off);
  }
  return buf[off];
}

function main() {
  const path = process.argv[2];
  if (!path) {
    process.stderr.write('usage: node extract.js <elf-binary>\n');
    process.exit(2);
  }

  const buf = fs.readFileSync(path);

  // ---- ELF identification -------------------------------------------------
  if (
    buf.length < 16 ||
    buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46
  ) {
    throw new Error('not an ELF file');
  }

  const eiClass = buf[4]; // 1 = ELF32, 2 = ELF64
  const eiData = buf[5];  // 1 = little-endian, 2 = big-endian
  const is64 = eiClass === 2;
  const le = eiData !== 2;

  const u16 = (off) => readUInt(buf, off, 2, le);
  const u32 = (off) => readUInt(buf, off, 4, le);
  const u64 = (off) => readUInt(buf, off, 8, le);
  const addrSize = is64 ? 8 : 4;

  // ---- Section headers (only needed to find relocation targets) ----------
  const eShoff = is64 ? Number(u64(0x28)) : Number(u32(0x20));
  const eShentsize = u16(is64 ? 0x3a : 0x2e);
  const eShnum = u16(is64 ? 0x3c : 0x30);

  // Addresses written by dynamic relocations.  Static extraction cannot know
  // the values a dynamic linker would resolve, so those words are omitted.
  const relocTargets = [];

  const shdr = (i) => {
    const off = eShoff + i * eShentsize;
    if (off + eShentsize > buf.length) return null;
    if (is64) {
      return {
        type: u32(off + 4),
        offset: Number(u64(off + 24)),
        size: Number(u64(off + 32)),
        entsize: Number(u64(off + 56)),
      };
    }
    return {
      type: u32(off + 4),
      offset: Number(u32(off + 16)),
      size: Number(u32(off + 20)),
      entsize: Number(u32(off + 36)),
    };
  };

  if (eShoff !== 0 && eShnum > 0) {
    for (let i = 0; i < eShnum; i++) {
      const sh = shdr(i);
      if (!sh) break;
      const isRela = sh.type === 4; // SHT_RELA
      const isRel = sh.type === 9;  // SHT_REL
      if (!isRela && !isRel) continue;

      const entsize = sh.entsize || (is64 ? (isRela ? 24 : 16) : (isRela ? 12 : 8));
      if (entsize === 0) continue;

      for (let off = sh.offset; off + entsize <= sh.offset + sh.size; off += entsize) {
        if (off + addrSize > buf.length) break;
        let rOffset;
        if (is64) {
          rOffset = Number(u64(off));
        } else {
          rOffset = Number(u32(off));
        }
        relocTargets.push(rOffset);
      }
    }
  }

  // Returns true if the 4-byte word at `addr` overlaps a relocation slot.
  const relocSlotSize = is64 ? 8 : 4;
  const overlapsReloc = (addr) => {
    const wordEnd = addr + 3;
    for (const r of relocTargets) {
      if (addr <= r + relocSlotSize - 1 && r <= wordEnd) return true;
    }
    return false;
  };

  // ---- Program headers ----------------------------------------------------
  const ePhoff = is64 ? Number(u64(0x20)) : Number(u32(0x1c));
  const ePhentsize = u16(is64 ? 0x36 : 0x2a);
  const ePhnum = u16(is64 ? 0x38 : 0x2c);

  const memory = {};

  for (let i = 0; i < ePhnum; i++) {
    const off = ePhoff + i * ePhentsize;
    if (off + ePhentsize > buf.length) break;

    const pType = u32(off);
    if (pType !== 1) continue; // PT_LOAD only

    let pOffset, pVaddr, pFilesz, pMemsz;
    if (is64) {
      pOffset = Number(u64(off + 8));
      pVaddr = Number(u64(off + 16));
      pFilesz = Number(u64(off + 32));
      pMemsz = Number(u64(off + 40));
    } else {
      pOffset = Number(u32(off + 4));
      pVaddr = Number(u32(off + 8));
      pFilesz = Number(u32(off + 16));
      pMemsz = Number(u32(off + 20));
    }

    // Only complete, file-backed 4-byte words are emitted.  Zero-filled
    // memory past p_filesz and any trailing partial word are skipped: their
    // presence/value depends on loader details we cannot verify.
    const limit = Math.min(pFilesz, pMemsz);
    for (let j = 0; j + 4 <= limit; j += 4) {
      const fileOff = pOffset + j;
      if (fileOff + 4 > buf.length) break;

      const address = LOAD_BASE + pVaddr + j;
      if (overlapsReloc(address)) continue;

      let value;
      if (le) {
        value = buf.readUInt32LE(fileOff);
      } else {
        value = buf.readUInt32BE(fileOff);
      }
      memory[address] = value;
    }
  }

  process.stdout.write(JSON.stringify(memory) + '\n');
}

main();

