// Returns true if the 4-byte word at `addr` overlaps a relocation slot.
// r_offset is a link-time virtual address, so it is shifted by LOAD_BASE
// just like the segment addresses.
const relocSlotSize = is64 ? 8 : 4;
const overlapsReloc = (addr) => {
  const wordEnd = addr + 3;
  for (const r of relocTargets) {
    const slotStart = LOAD_BASE + r;
    if (addr <= slotStart + relocSlotSize - 1 && slotStart <= wordEnd) {
      return true;
    }
  }
  return false;
};

